ALTER TABLE "Product"
  ADD COLUMN "sourceUrl" TEXT,
  ADD COLUMN "documents" JSONB,
  ADD COLUMN "specifications" JSONB,
  ADD COLUMN "translations" JSONB;

CREATE TABLE "ContentPage" (
  "id" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "content" JSONB NOT NULL,
  "active" BOOLEAN NOT NULL DEFAULT true,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "ContentPage_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ContentPage_slug_key" ON "ContentPage"("slug");
CREATE INDEX "ContentPage_active_sortOrder_idx" ON "ContentPage"("active", "sortOrder");

UPDATE "Product"
SET "sourceUrl" = 'https://xion.uz/uz/mahsulotlar-katalogi/',
    "specifications" = jsonb_build_object(
      'usage', 'Faqat professional tibbiy foydalanish uchun',
      'manufacturer', 'Simurg tibbiyot korxonasi, Belarus',
      'availability', 'Mavjudlik va modifikatsiya operator bilan aniqlashtiriladi'
    ),
    "translations" = NULL,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "id" LIKE 'xion-product-%';

