INSERT INTO "Product" (
  "id", "title", "slug", "shortDescription", "longDescription", "image", "sourceUrl", "documents",
  "specifications", "category", "active", "featured", "sortOrder", "createdAt", "updatedAt"
)
VALUES (
  'xion-product-046', 'Akusherlik yengillashtiruvchi silikon pessariy', 'akusherlik-yengillashtiruvchi-silikon-pessariy',
  'Homiladorlik davrida bachadon bo‘yniga tushadigan yukni qayta taqsimlash uchun tibbiy silikon pessariy.',
  'Akusherlik yengillashtiruvchi pessariy istmiko-servikal yetishmovchilik va muddatidan oldin tug‘ruq xavfi mavjud holatlarda mutaxassis tomonidan tanlanadi. O‘lcham, o‘rnatish va nazorat faqat akusher-ginekolog tomonidan belgilanadi.',
  'https://xion.uz/data/uploads/module/shop/products//239/694x614/6a0306a18e8de.png',
  'https://xion.uz/uz/akusherlik-yengillashtiruvchi-silikon-pessariy/',
  $$[
    {"label":"Ro‘yxatdan o‘tganlik guvohnomasi","url":"https://xion.uz/data/uploads/docs/%D0%A0%D0%B5%D0%B3.%20%D0%A3%D0%B4%D0%BE%D1%81%D1%82%D0%BE%D0%B2%D0%B5%D1%80%D0%B5%D0%BD%D0%B8%D0%B5/2022%20%D0%A2%D0%92-%D0%A5-%D0%A2%D0%9E%2005342-06-22%20%D0%9F%D0%90%D0%A0.pdf"},
    {"label":"Foydalanish bo‘yicha yo‘riqnoma","url":"https://simurg-mp.com/instrukzii/instrukcziya-pessarij-akusherskij-razgruzhayushhij-silikonovyij.pdf"}
  ]$$::jsonb,
  $${"material":"Tibbiy silikon","usage":"Faqat akusher-ginekolog nazoratida","manufacturer":"Simurg, Belarus"}$$::jsonb,
  'Akusherlik pessariylari', true, true, 46, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
);

