VALUES (
  'xion-product-047', 'Bachadon bo‘yni uchun perforatsiyali silikon pessariy', 'bachadon-boyni-perforatsiyali-silikon-pessariy',
  'Bachadon bo‘ynini qo‘llab-quvvatlash uchun perforatsiyali tibbiy silikon pessariy.',
