  'https://xion.uz/uz/silikon-pessariy-bachadon-boyni-uchun-teshikli-perforatsiyalangan/',
  $$[
    {"label":"Ro‘yxatdan o‘tganlik guvohnomasi","url":"https://xion.uz/data/uploads/docs/%D0%A0%D0%B5%D0%B3.%20%D0%A3%D0%B4%D0%BE%D1%81%D1%82%D0%BE%D0%B2%D0%B5%D1%80%D0%B5%D0%BD%D0%B8%D0%B5/2022%20%D0%A2%D0%92-%D0%A5-%D0%A2%D0%9E%2005343-06-22%20%D0%9F%D0%A1.pdf"},
    {"label":"Foydalanish bo‘yicha yo‘riqnoma","url":"https://simurg-mp.com/instrukzii/instrukcziya-ps-czervikalnyij-perforirovannyij.pdf"}
  ]$$::jsonb,
  $${"material":"Tibbiy silikon","type":"Servikal, perforatsiyali","usage":"Faqat akusher-ginekolog nazoratida","manufacturer":"Simurg, Belarus"}$$::jsonb,
