INSERT INTO "ContentPage" ("id", "slug", "title", "content", "active", "sortOrder", "createdAt", "updatedAt") VALUES
('xion-page-about', 'about', 'Kompaniya haqida', $${
  "sourceUrl":"https://xion.uz/uz/kompaniya-haqida/",
  "uz":{"eyebrow":"NOVA HAQIDA","title":"Tibbiy yechimlar bo‘yicha ishonchli hamkor","excerpt":"Akusherlik, ginekologiya va urologiya uchun tekshirilgan tibbiy buyumlar yetkazib beramiz.","sections":[
    {"title":"Kompaniya imkoniyatlari","text":"Bozordagi 10 yildan ortiq tajriba klinikalar ehtiyojini chuqur tushunish va barqaror yetkazib berish tizimini yaratishga yordam berdi.","items":["Assortimentning qariyb 90 foizi omborda","Bir donadan boshlab ulgurji va chakana buyurtma","Talablarga muvofiq saqlash","Har bir mahsulot uchun ruxsat hujjatlari"]},
    {"title":"Missiya","text":"Zamonaviy tibbiy buyumlarni O‘zbekiston bo‘ylab o‘z vaqtida yetkazib, tibbiyot muassasalari va mutaxassislar ishini qo‘llab-quvvatlash."},
    {"title":"Rivojlanish","text":"2024-yilda biznes jarayonlari avtomatlashtirildi. 2025-yilda assortiment va ombor quvvati kengaytirildi."}
  ]},
  "ru":{"eyebrow":"О NOVA","title":"Надёжный партнёр в медицинских решениях","excerpt":"Изделия для акушерства, гинекологии и урологии.","sections":[{"title":"Опыт и наличие","text":"Более 10 лет на рынке, около 90% ассортимента на складе, оптовые и розничные заказы от одной единицы.","items":["Разрешительная документация","Правильное хранение","Доставка по Узбекистану"]}]},
  "en":{"eyebrow":"ABOUT NOVA","title":"A trusted medical supply partner","excerpt":"Products for obstetrics, gynecology and urology.","sections":[{"title":"Experience and availability","text":"More than 10 years in the market, around 90% of the range in stock, with wholesale and retail orders from one unit.","items":["Regulatory documents","Controlled storage","Delivery across Uzbekistan"]}]}
}$$::jsonb, true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-simurg', 'simurg', 'Simurg kompaniyasi', $${
  "sourceUrl":"https://xion.uz/ru/kompaniya-simurg/",
  "uz":{"eyebrow":"RASMIY HAMKOR","title":"Simurg tibbiyot korxonasi","excerpt":"1991-yildan buyon akusherlik, ginekologiya va urologiya uchun tibbiy buyumlar ishlab chiqaruvchi Belarus korxonasi.","sections":[
    {"title":"Bugungi Simurg","text":"Mahsulotlar 25 dan ortiq mamlakatda qo‘llanadi. Korxona 70 dan ortiq buyum turi va 200 dan ortiq modifikatsiyani taklif qiladi.","items":["EN ISO 13485:2016 sifat tizimi","CE sertifikatlangan silikon pessariylar","Shifokorlar uchun ekspert ko‘magi"]},
    {"title":"Muhim bosqichlar","text":"2019-yilda Medica xalqaro ko‘rgazmasida qatnashildi; 2020-yilda ISO va CE sertifikatlari olindi; 2021-yilda urogenital floklangan zondlar uchun ikkinchi avtomatik liniya ishga tushirildi."},
    {"title":"Yunona savdo belgisi","text":"Yunona turkumi bachadon ichi kontratseptivlari, pessariylar va akusherlik-ginekologik asboblarni birlashtiradi."}
  ]},
  "ru":{"eyebrow":"ОФИЦИАЛЬНЫЙ ПАРТНЁР","title":"Медицинское предприятие «Симург»","excerpt":"Белорусский производитель с 1991 года.","sections":[{"title":"Масштаб","text":"Более 70 видов изделий, свыше 200 модификаций и поставки более чем в 25 стран.","items":["EN ISO 13485:2016","CE","Поддержка врачей"]}]},
  "en":{"eyebrow":"OFFICIAL PARTNER","title":"Simurg Medical Enterprise","excerpt":"A Belarusian manufacturer operating since 1991.","sections":[{"title":"Scale","text":"Over 70 product types, more than 200 modifications and distribution in 25+ countries.","items":["EN ISO 13485:2016","CE","Clinical support"]}]}
}$$::jsonb, true, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-catalog', 'catalog-info', 'Katalog haqida', $${
  "sourceUrl":"https://xion.uz/uz/mahsulotlar-katalogi/",
  "uz":{"eyebrow":"KATALOG","title":"Akusherlik va ginekologiya uchun mahsulotlar","excerpt":"Rasmiy distributordan to‘liq o‘lchamlar qatori va O‘zbekiston bo‘ylab yetkazib berish.","sections":[
    {"title":"Yo‘nalishlar","text":"Katalog professional foydalanish uchun mo‘ljallangan tibbiy buyumlarni jamlaydi.","items":["Akusherlik pessariylari","Ginekologik pessariylar","Bachadon ichi vositalari","Bir martalik asboblar","Ginekologik ko‘zgu va to‘plamlar"]},
    {"title":"Nega NOVA","text":"Keng assortiment, tezkor jo‘natish, to‘liq o‘lchamlar qatori va sifat talablariga muvofiqlik."}
  ]},
  "ru":{"eyebrow":"КАТАЛОГ","title":"Изделия для акушерства и гинекологии","excerpt":"Размерный ряд и доставка по Узбекистану.","sections":[{"title":"Категории","text":"Внутриматочные средства, пессарии, одноразовые инструменты и гинекологические наборы."}]},
  "en":{"eyebrow":"CATALOGUE","title":"Obstetric and gynecological products","excerpt":"A broad size range with delivery across Uzbekistan.","sections":[{"title":"Categories","text":"Intrauterine devices, pessaries, disposable instruments and gynecological sets."}]}
}$$::jsonb, true, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-medical', 'medical-institutions', 'Tibbiyot muassasalari uchun', $${
  "sourceUrl":"https://xion.uz/uz/tibbiyot-muassasalari-uchun/","form":"medical_institutions",
  "uz":{"eyebrow":"B2B HAMKORLIK","title":"Tibbiyot muassasalari uchun to‘g‘ridan-to‘g‘ri yetkazib berish","excerpt":"Mahsulotlar ishlab chiqaruvchi zavodlardan vositachilarsiz xarid qilinadi.","sections":[
    {"title":"Kimlar uchun","items":["Xususiy klinikalar","Davlat tibbiyot muassasalari","Dorixona tarmoqlari","Shifokorlar va yakka tartibdagi tadbirkorlar"]},
    {"title":"Afzalliklar","text":"To‘g‘ridan-to‘g‘ri narxlar, shaffof shartlar, logistika va ishlab chiqaruvchi bilan ishlashni to‘liq kuzatish.","items":["10+ yillik tajriba","Keng assortiment","Hujjatlar bilan ta’minlash","Vaqt va resursni tejash"]}
  ]},
  "ru":{"eyebrow":"B2B","title":"Для медицинских учреждений","excerpt":"Прямые поставки от производителей.","sections":[{"title":"Для кого","items":["Частные клиники","Государственные учреждения","Аптечные сети","Практикующие врачи"]}]},
  "en":{"eyebrow":"B2B","title":"For medical institutions","excerpt":"Direct manufacturer supply.","sections":[{"title":"Who it is for","items":["Private clinics","Public institutions","Pharmacy chains","Medical practitioners"]}]}
}$$::jsonb, true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-manufacturers', 'manufacturers', 'Ishlab chiqaruvchilar uchun', $${
  "sourceUrl":"https://xion.uz/uz/ishlab-chiqaruvchilar-uchun/","form":"manufacturers",
  "uz":{"eyebrow":"BOZORGA KIRISH","title":"Ishlab chiqaruvchilar uchun to‘liq vakillik","excerpt":"Mahsulotni sotish bilan cheklanmay, uning brendini O‘zbekiston bozorida rivojlantiramiz.","sections":[
    {"title":"Yordam yo‘nalishlari","items":["Talab va raqobatchilar tahlili","Yangi xaridorlarni jalb qilish","Tibbiyot mutaxassislari orasida brend nufuzini shakllantirish","Onlayn va bevosita savdo kanallari"]},
    {"title":"Hamkorlik paketi","items":["Mijoz va tibbiyot muassasalari tarmog‘ida targ‘ibot","Ko‘rgazma va taqdimotlarda ishtirok","Savdo strategiyasi va marketing","Qadoq va markirovkani mahalliylashtirish","O‘zbekistonda ro‘yxatdan o‘tkazish va sertifikatlash"]}
  ]},
  "ru":{"eyebrow":"ВЫХОД НА РЫНОК","title":"Для производителей","excerpt":"Развиваем бренд на рынке Узбекистана.","sections":[{"title":"Полный цикл","items":["Анализ рынка","Маркетинг и продажи","Локализация упаковки","Регистрация и сертификация"]}]},
  "en":{"eyebrow":"MARKET ENTRY","title":"For manufacturers","excerpt":"We develop medical brands in Uzbekistan.","sections":[{"title":"Full cycle","items":["Market analysis","Marketing and sales","Packaging localization","Registration and certification"]}]}
}$$::jsonb, true, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-news', 'news', 'Yangiliklar', $${
  "sourceUrl":"https://xion.uz/uz/yangiliklar/",
  "uz":{"eyebrow":"YANGILIKLAR","title":"Kompaniya yangiliklari","excerpt":"Mahsulotlar, hamkorlik va servis yangiliklari.","sections":[{"title":"Yangi onlayn platforma ishga tushdi","date":"2025-12-28","text":"Mijozlar bilan aloqani yaxshilash, dolzarb katalogni taqdim etish va xizmatlardan foydalanishni yengillashtirish uchun yangi sayt ishga tushirildi."}]},
  "ru":{"eyebrow":"НОВОСТИ","title":"Новости компании","excerpt":"Продукты, партнёрство и сервис.","sections":[{"title":"Запущена новая онлайн-платформа","date":"2025-12-28","text":"Новый сайт упрощает доступ к каталогу и связь со специалистами."}]},
  "en":{"eyebrow":"NEWS","title":"Company news","excerpt":"Products, partnerships and service updates.","sections":[{"title":"New online platform launched","date":"2025-12-28","text":"The new website makes the catalogue and specialist support easier to access."}]}
}$$::jsonb, true, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-career', 'career', 'Karyera', $${
  "sourceUrl":"https://xion.uz/uz/karyera/","form":"career",
  "uz":{"eyebrow":"KARYERA","title":"Professional jamoaga qo‘shiling","excerpt":"Tibbiy distributsiya yo‘nalishiga qiziqqan faol mutaxassislar uchun imkoniyatlar.","sections":[
    {"title":"NOVA’da ishlash","items":["Munosib va barqaror mehnat haqi","Xalqaro standartlar asosidagi ish","Professional o‘sish","Rasmiy ishga joylashish","Tajribali jamoa","Muntazam malaka oshirish"]},
    {"title":"Ochiq vakansiya","text":"Marketing bo‘limi mutaxassisi — to‘liq ish kuni. Rezyume va tajribangiz haqida murojaat formasida yozing."}
  ]},
  "ru":{"eyebrow":"КАРЬЕРА","title":"Присоединяйтесь к команде","excerpt":"Возможности для специалистов медицинской дистрибуции.","sections":[{"title":"Условия","items":["Стабильная оплата","Официальное трудоустройство","Профессиональный рост","Опытная команда"]}]},
  "en":{"eyebrow":"CAREERS","title":"Join the team","excerpt":"Opportunities in medical distribution.","sections":[{"title":"Benefits","items":["Stable compensation","Official employment","Professional growth","Experienced team"]}]}
}$$::jsonb, true, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-contact', 'contact', 'Aloqa va FAQ', $${
  "sourceUrl":"https://xion.uz/uz/aloqa/","form":"contact",
  "uz":{"eyebrow":"ALOQA","title":"Savolingiz bormi?","excerpt":"Mahsulot tanlash, mavjudlik, yetkazish yoki hamkorlik bo‘yicha yozing.","sections":[
    {"title":"Tez-tez beriladigan savollar","faqs":[
      {"question":"Kompaniya nima bilan shug‘ullanadi?","answer":"Akusherlik, ginekologiya va urologiya uchun tibbiy asbob va sarf materiallarini ro‘yxatdan o‘tkazishdan yetkazib berishgacha bo‘lgan to‘liq siklda ishlaydi."},
      {"question":"Kimlar bilan ishlaysiz?","answer":"Xususiy va davlat klinikalari, dorixona tarmoqlari, ishlab chiqaruvchilar, amaliyotchi shifokorlar va tadbirkorlar bilan."},
      {"question":"Mahsulot tanlash bo‘yicha maslahat beriladimi?","answer":"Ha, muassasa yoki mutaxassis ehtiyojiga mos individual tanlov bo‘yicha konsultatsiya mavjud."},
      {"question":"Ofis va ish vaqti?","answer":"Toshkent shahri, Olmazor tumani, Allon ko‘chasi 141A. Dushanba–Juma, 08:00–17:00."}
    ]}
  ]},
  "ru":{"eyebrow":"КОНТАКТЫ","title":"Остались вопросы?","excerpt":"Напишите по вопросам продукции, доставки или сотрудничества.","sections":[{"title":"Консультация","text":"Специалист поможет подобрать изделие и уточнит условия поставки."}]},
  "en":{"eyebrow":"CONTACT","title":"Have a question?","excerpt":"Contact us about products, delivery or partnership.","sections":[{"title":"Consultation","text":"A specialist will help select a product and confirm supply terms."}]}
}$$::jsonb, true, 8, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-warranty', 'warranty-return', 'Kafolat va qaytarish', $${
  "sourceUrl":"https://xion.uz/uz/kafolat-va-qaytarish/",
  "uz":{"eyebrow":"HUQUQIY MA’LUMOT","title":"Kafolat va qaytarish","excerpt":"Tibbiy buyumlar uchun ishlab chiqaruvchi kafolati va reklamatsiya tartibi.","sections":[
    {"title":"Kafolat","text":"Kafolat muddati mahsulotning texnik hujjati yoki talonida ko‘rsatiladi va foydalanish, saqlash, tashish hamda sterilizatsiya talablariga rioya qilinganda amal qiladi."},
    {"title":"Qaytarish","text":"Tegishli sifatdagi tibbiy va sanitariya-gigiyena buyumlari qonunchilikdagi cheklovlarga ko‘ra odatda qaytarilmaydi yoki almashtirilmaydi. Buyurtmani qabul qilishda model va komplektatsiyani tekshiring."},
    {"title":"Nuqson aniqlansa","items":["Xaridni tasdiqlovchi hujjat","Foto yoki video dalil","Nosozlik va foydalanish sharoiti yozilgan dalolatnoma"]},
    {"title":"Kafolatdan tashqari holatlar","items":["Mexanik shikast","Noto‘g‘ri tashish yoki sterilizatsiya","Tabiiy eskirish","Kelishilmagan ta’mir yoki o‘zgartirish","Maqsadsiz foydalanish"]}
  ]},
  "ru":{"eyebrow":"ПРАВОВАЯ ИНФОРМАЦИЯ","title":"Гарантия и возврат","excerpt":"Гарантия производителя и порядок рекламаций.","sections":[{"title":"Основные условия","text":"Срок указан в документации. Возврат медицинских изделий ограничен законом; при дефекте нужны документы о покупке и подтверждающие материалы."}]},
  "en":{"eyebrow":"LEGAL","title":"Warranty and returns","excerpt":"Manufacturer warranty and claim process.","sections":[{"title":"Core terms","text":"The warranty period is stated in product documents. Returns of medical products are legally restricted; defect claims require purchase and supporting evidence."}]}
}$$::jsonb, true, 9, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-terms', 'terms', 'Saytdan foydalanish qoidalari', $${
  "sourceUrl":"https://xion.uz/uz/saytdan-foydalanish-qoidalari/",
  "uz":{"eyebrow":"HUQUQIY MA’LUMOT","title":"Saytdan foydalanish qoidalari","excerpt":"NOVA katalogi axborot berish va so‘rov qabul qilish uchun ishlaydi.","sections":[
    {"title":"Axborot xususiyati","text":"Saytdagi tavsif shifokor maslahati yoki foydalanish yo‘riqnomasini almashtirmaydi. Mahsulot tanlash va qo‘llash faqat malakali tibbiyot xodimi tomonidan bajariladi."},
    {"title":"Buyurtma","text":"Forma yuborilishi oldi-sotdi shartnomasi tuzilganini anglatmaydi. Narx, sertifikat, mavjudlik va yetkazish shartlari menejer bilan kelishiladi."},
    {"title":"Kontent","text":"Rasm, katalog va tavsiflardan tijorat maqsadida foydalanish tegishli huquq egasining ruxsatini talab qiladi."}
  ]},
  "ru":{"eyebrow":"ПРАВОВАЯ ИНФОРМАЦИЯ","title":"Правила использования сайта","excerpt":"Каталог носит информационный характер.","sections":[{"title":"Важно","text":"Информация не заменяет консультацию врача. Отправка формы не является договором купли-продажи."}]},
  "en":{"eyebrow":"LEGAL","title":"Terms of use","excerpt":"The catalogue is provided for information and enquiries.","sections":[{"title":"Important","text":"Information does not replace medical advice. Submitting a form does not create a sales contract."}]}
}$$::jsonb, true, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),

('xion-page-privacy', 'privacy', 'Maxfiylik siyosati', $${
  "sourceUrl":"https://xion.uz/uz/maxfiylik-siyosati/",
  "uz":{"eyebrow":"HUQUQIY MA’LUMOT","title":"Maxfiylik siyosati","excerpt":"Murojaatlar va sayt ishlashi uchun kerak bo‘lgan ma’lumotlarni qayta ishlash qoidalari.","sections":[
    {"title":"Yig‘iladigan ma’lumotlar","items":["Ism, telefon va e-mail","So‘rov yoki buyurtma mazmuni","IP, brauzer, cookie, kirish va sahifa ma’lumotlari"]},
    {"title":"Maqsad","text":"Foydalanuvchini aniqlash, murojaatni qayta ishlash, mos xizmat ko‘rsatish va sayt sifatini yaxshilash."},
    {"title":"Uzatish va himoya","text":"Ma’lumot rozilik, xizmat ko‘rsatish zarurati yoki qonun talabi mavjud bo‘lgandagina uchinchi tomonga uzatiladi. Noqonuniy kirish va tarqatishdan himoya choralari qo‘llanadi."},
    {"title":"Foydalanuvchi huquqi","text":"Foydalanuvchi aloqa kanallari orqali o‘z ma’lumotini o‘zgartirish yoki o‘chirishni so‘rashi mumkin."}
  ]},
